# ============================================================================
#  Security.ps1
#   * PBKDF2-HMAC-SHA1 password hashing (salted, 120k iterations)
#   * Server-side sessions with an HttpOnly cookie
#   * CSRF tokens on every state-changing form
#   * Page guards that redirect anonymous visitors to the login page
# ============================================================================

# ---------------------------------------------------------- password hashing --
function New-PasswordRecord {
    <#
        Returns only salt + hash + iteration count. The clear-text password is
        never stored, never logged and never returned to the client.
    #>
    param([Parameter(Mandatory = $true)][string]$Password)

    $salt      = New-RandomBytes -Count 16
    $iterations = [int]$global:Config.Pbkdf2Iterations
    $hash      = Get-Pbkdf2 -Password $Password -Salt $salt -Iterations $iterations

    return [pscustomobject]@{
        passwordSalt      = (ConvertTo-Base64Url $salt)
        passwordHash      = (ConvertTo-Base64Url $hash)
        passwordAlgorithm = 'PBKDF2-HMAC-SHA1'
        passwordIterations = $iterations
    }
}

function Get-Pbkdf2 {
    param([string]$Password, [byte[]]$Salt, [int]$Iterations, [int]$Length = 32)
    $derive = New-Object System.Security.Cryptography.Rfc2898DeriveBytes `
        -ArgumentList ([System.Text.Encoding]::UTF8.GetBytes($Password)), $Salt, $Iterations
    try {
        return $derive.GetBytes($Length)
    } finally {
        $derive.Dispose()
    }
}

function Test-PasswordAgainstRecord {
    param([string]$Password, $User)

    if ($null -eq $User) { return $false }
    if ([string]::IsNullOrWhiteSpace([string]$User.passwordHash)) { return $false }
    if ([string]::IsNullOrWhiteSpace([string]$User.passwordSalt)) { return $false }

    $iterations = 120000
    if ($User.PSObject.Properties.Name -contains 'passwordIterations' -and $User.passwordIterations) {
        $iterations = [int]$User.passwordIterations
    }

    $expected = ConvertFrom-Base64Url ([string]$User.passwordHash)
    $actual   = Get-Pbkdf2 -Password $Password -Salt (ConvertFrom-Base64Url ([string]$User.passwordSalt)) `
                           -Iterations $iterations -Length $expected.Length

    # Constant-time comparison to avoid leaking information through timing
    if ($expected.Length -ne $actual.Length) { return $false }
    $diff = 0
    for ($i = 0; $i -lt $expected.Length; $i++) {
        $diff = $diff -bor ($expected[$i] -bxor $actual[$i])
    }
    return ($diff -eq 0)
}

function Set-UserPassword {
    param($User, [string]$Password)
    $record = New-PasswordRecord -Password $Password
    $User | Add-Member -NotePropertyName 'passwordSalt'       -NotePropertyValue $record.passwordSalt       -Force
    $User | Add-Member -NotePropertyName 'passwordHash'       -NotePropertyValue $record.passwordHash       -Force
    $User | Add-Member -NotePropertyName 'passwordAlgorithm'  -NotePropertyValue $record.passwordAlgorithm  -Force
    $User | Add-Member -NotePropertyName 'passwordIterations' -NotePropertyValue $record.passwordIterations -Force
    $User | Add-Member -NotePropertyName 'passwordChangedAt'  -NotePropertyValue (Get-NowIso)                 -Force
    Save-User $User
    return $User
}

# ------------------------------------------------------------------- users --
function New-UserRecord {
    param(
        [string]$Name,
        [string]$Email,
        [string]$Password,
        [ValidateSet('admin', 'resident')][string]$Role = 'resident',
        [string]$Phone = '',
        [string]$Address = '',
        [bool]$Active = $true
    )

    $user = [pscustomobject]@{
        id                 = (New-Id 'usr')
        name               = $Name.Trim()
        email              = $Email.Trim().ToLowerInvariant()
        role               = $Role
        phone              = $Phone
        address            = $Address
        active             = $Active
        createdAt          = (Get-NowIso)
        updatedAt          = (Get-NowIso)
        lastLoginAt        = ''
        passwordSalt       = ''
        passwordHash       = ''
        passwordAlgorithm  = ''
        passwordIterations = 0
        passwordChangedAt  = ''
    }
    $user = Set-UserPassword -User $user -Password $Password
    Save-User $user
    return $user
}

function Get-Initials {
    param([string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name)) { return '?' }
    $parts = ($Name -split '\s+') | Where-Object { $_ -ne '' }
    if ($parts.Count -eq 0) { return '?' }
    if ($parts.Count -eq 1) { return $parts[0].Substring(0, 1).ToUpperInvariant() }
    return (($parts[0].Substring(0, 1) + $parts[-1].Substring(0, 1)).ToUpperInvariant())
}

function Test-IsAdmin {
    param($User)
    return ($null -ne $User -and [string]$User.role -eq 'admin')
}

# ---------------------------------------------------------------- sessions --
function New-Session {
    param([string]$UserId)

    $now   = [DateTime]::UtcNow
    $entry = [pscustomobject]@{
        token      = (ConvertTo-Base64Url (New-RandomBytes -Count 32))
        csrfToken  = (ConvertTo-Base64Url (New-RandomBytes -Count 24))
        userId     = $UserId
        createdAt  = $now.ToString('o')
        expiresAt  = $now.AddHours([int]$global:Config.SessionHours).ToString('o')
        lastSeenAt = $now.ToString('o')
        userAgent  = ''
    }

    $sessions = @(Get-AllSessions)
    $sessions += $entry
    $global:Db.sessions = @($sessions)
    Save-Database
    return $entry
}

function Get-AllSessions { return @($global:Db.sessions) }

function Get-SessionByToken {
    param([string]$Token)
    if ([string]::IsNullOrWhiteSpace($Token)) { return $null }
    return (@(Get-AllSessions) | Where-Object { $_.token -eq $Token } | Select-Object -First 1)
}

function Remove-ExpiredSessions {
    $now = [DateTime]::UtcNow
    $kept = @(@(Get-AllSessions) | Where-Object {
        $expiry = Get-DateTimeFromIso ([string]$_.expiresAt)
        $expiry -gt $now
    })
    if ($kept.Count -ne @(Get-AllSessions).Count) {
        $global:Db.sessions = @($kept)
        return $true
    }
    return $false
}

function Remove-SessionByToken {
    param([string]$Token)
    if ([string]::IsNullOrWhiteSpace($Token)) { return }
    $global:Db.sessions = @(@(Get-AllSessions) | Where-Object { $_.token -ne $Token })
    Save-Database
}

function Remove-AllSessionsForUser {
    param([string]$UserId)
    $global:Db.sessions = @(@(Get-AllSessions) | Where-Object { $_.userId -ne $UserId })
    Save-Database
}

# -------------------------------------------------------------- http cookies --
function Send-SessionCookie {
    param($Response, [string]$Token)
    $maxAge = [int]$global:Config.SessionHours * 3600
    $cookie = '{0}={1}; Path=/; Max-Age={2}; HttpOnly; SameSite=Lax' -f `
        $global:Config.CookieName, $Token, $maxAge
    try { $Response.Headers['Set-Cookie'] = $cookie } catch { }
}

function Clear-SessionCookie {
    param($Response)
    $cookie = '{0}=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax' -f $global:Config.CookieName
    try { $Response.Headers['Set-Cookie'] = $cookie } catch { }
}

function Get-RequestCookie {
    param($Request, [string]$Name)
    try {
        $cookie = $Request.Cookies[$Name]
        if ($null -ne $cookie) { return [string]$cookie.Value }
    } catch { }
    return ''
}

# ---------------------------------------------------------------- auth flow --
function Get-AuthContext {
    param($Request)

    $context = @{ User = $null; Session = $null; Token = '' }

    $token = Get-RequestCookie -Request $Request -Name $global:Config.CookieName
    if ([string]::IsNullOrWhiteSpace($token)) { return $context }

    $session = Get-SessionByToken -Token $token
    if ($null -eq $session) { return $context }

    $expiry = Get-DateTimeFromIso ([string]$session.expiresAt)
    if ($expiry -le [DateTime]::UtcNow) {
        Remove-SessionByToken -Token $token
        return $context
    }

    $user = Get-UserById $session.userId
    if ($null -eq $user) {
        Remove-SessionByToken -Token $token
        return $context
    }

    # Deactivated accounts are logged out immediately, even mid-session.
    if ($user.PSObject.Properties.Name -contains 'active' -and -not [bool]$user.active) {
        Remove-SessionByToken -Token $token
        return $context
    }

    $context.User    = $user
    $context.Session = $session
    $context.Token   = $token
    return $context
}

function Start-UserSession {
    param($User, $Response, $Request)

    $session = New-Session -UserId $User.id
    Send-SessionCookie -Response $Response -Token $session.token

    $User | Add-Member -NotePropertyName 'lastLoginAt' -NotePropertyValue (Get-NowIso) -Force
    $User | Add-Member -NotePropertyName 'loginCount'   -NotePropertyValue ([int]$User.loginCount + 1) -Force
    Save-User $User

    Add-ActivityLog -Action 'login' -ActorId $User.id -Detail ('Signed in as ' + $User.role)
    return $session
}

function End-UserSession {
    param($Ctx, $Response)

    if ($null -ne $Ctx.Auth -and -not [string]::IsNullOrWhiteSpace($Ctx.Auth.Token)) {
        Remove-SessionByToken -Token $Ctx.Auth.Token
    }
    Clear-SessionCookie -Response $Response
}

function Get-CsrfToken {
    param($Ctx)
    if ($null -eq $Ctx.Auth -or $null -eq $Ctx.Auth.Session) { return '' }
    return [string]$Ctx.Auth.Session.csrfToken
}

function Test-CsrfToken {
    param($Ctx)
    $expected = Get-CsrfToken -Ctx $Ctx
    $provided = Get-FormValue -Body $Ctx.Body -Name 'csrf_token'
    if ([string]::IsNullOrWhiteSpace($expected)) { return $false }
    if ([string]::IsNullOrWhiteSpace($provided)) { return $false }
    return ($expected -eq $provided)
}

# ------------------------------------------------------------- page guards --
function Protect-Page {
    <#
        Returns $true when the request may continue. Otherwise it emits a
        302 redirect to /login (preserving the intended destination) and
        returns $false. This is what protects every account-only page.
    #>
    param($Ctx)

    if ($null -ne $Ctx.Auth -and $null -ne $Ctx.Auth.User) {
        return $true
    }

    $next = [System.Net.WebUtility]::UrlEncode([string]$Ctx.Path)
    $target = $Ctx.Path
    if (-not [string]::IsNullOrWhiteSpace([string]$Ctx.Request.QueryString.ToString())) {
        $target = $Ctx.Path + '?' + $Ctx.Request.QueryString.ToString()
    }
    $next = [System.Net.WebUtility]::UrlEncode($target)

    Send-Redirect -Response $Ctx.Response -Location ('/login?next=' + $next) -StatusCode 302
    return $false
}

function Protect-AdminPage {
    param($Ctx)

    if (-not (Protect-Page -Ctx $Ctx)) { return $false }

    if (Test-IsAdmin $Ctx.Auth.User) { return $true }

    Send-Html -Response $Ctx.Response -StatusCode 403 -Html (New-HtmlDocument `
        -Title 'Access denied' -ActiveNav '' -User $Ctx.Auth.User `
        -BodyHtml (New-ErrorBody -StatusCode 403 `
            -Heading 'Administrator access only' `
            -Message 'This page is limited to Barangay administrators. Your account is registered as a regular resident, so you can only view and manage your own reports.'))
    return $false
}

function Test-OwnsComplaint {
    param($Complaint, $User)
    if ($null -eq $Complaint -or $null -eq $User) { return $false }
    if (Test-IsAdmin $User) { return $true }
    return ([string]$Complaint.reporterId -eq [string]$User.id)
}

# ----------------------------------------------------------------- logging --
function Write-AuditLog {
    param($Ctx, [string]$Action, [string]$Detail)
    $actorId = ''
    if ($null -ne $Ctx.Auth -and $null -ne $Ctx.Auth.User) { $actorId = [string]$Ctx.Auth.User.id }
    Add-ActivityLog -Action $Action -ActorId $actorId -Detail $Detail
    Save-Database
}

# ============================================================================
#  Validation.ps1 - friendly, field-level input validation
# ============================================================================

function Test-EmailAddress {
    param([string]$Email)
    if ([string]::IsNullOrWhiteSpace($Email)) { return $false }
    if ($Email.Length -gt 190) { return $false }
    if ($Email -notmatch '^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$') { return $false }
    return $true
}

function Test-PhoneNumber {
    param([string]$Phone)
    if ([string]::IsNullOrWhiteSpace($Phone)) { return $true }   # optional field
    $digits = ($Phone -replace '[^0-9]')
    if ($digits.Length -lt 7 -or $digits.Length -gt 15) { return $false }
    return $true
}

function Test-PasswordPolicy {
    <#
        Minimum 8 characters, at least one letter and one number.
        Returns an error message, or $null when the password is acceptable.
    #>
    param([string]$Password)

    if ([string]::IsNullOrEmpty($Password)) {
        return 'Please choose a password.'
    }
    if ($Password.Length -lt 8) {
        return 'Your password must be at least 8 characters long.'
    }
    if ($Password.Length -gt 128) {
        return 'Your password is too long (maximum 128 characters).'
    }
    if ($Password -notmatch '[A-Za-z]') {
        return 'Your password must contain at least one letter.'
    }
    if ($Password -notmatch '[0-9]') {
        return 'Your password must contain at least one number.'
    }
    if ($Password -notmatch '[^A-Za-z0-9]') {
        return 'Your password must contain at least one special character (for example ! @ # %).'
    }
    return $null
}

function Add-FieldError {
    param([hashtable]$Errors, [string]$Field, [string]$Message)
    $Errors[$Field] = $Message
}

function Validate-RegistrationInput {
    param([hashtable]$Body, [string]$Mode = 'register')

    $errors = @{}
    $values = @{
        name     = (Get-FormValue -Body $Body -Name 'name')
        email    = (Get-FormValue -Body $Body -Name 'email')
        phone    = (Get-FormValue -Body $Body -Name 'phone')
        address  = (Get-FormValue -Body $Body -Name 'address')
        password = (Get-FormValue -Body $Body -Name 'password')
    }

    # --- name -----------------------------------------------------------
    if ([string]::IsNullOrWhiteSpace($values.name)) {
        Add-FieldError $errors 'name' 'Please enter your full name.'
    }
    elseif ($values.name.Length -lt 2) {
        Add-FieldError $errors 'name' 'Your name must be at least 2 characters long.'
    }
    elseif ($values.name.Length -gt 80) {
        Add-FieldError $errors 'name' 'Your name must be 80 characters or fewer.'
    }
    elseif ($values.name -notmatch "^[A-Za-zÀ-ÿ' .\-]+$") {
        Add-FieldError $errors 'name' 'Your name may only contain letters, spaces, apostrophes, periods and hyphens.'
    }

    # --- email ----------------------------------------------------------
    if ([string]::IsNullOrWhiteSpace($values.email)) {
        Add-FieldError $errors 'email' 'Please enter your email address.'
    }
    elseif (-not (Test-EmailAddress $values.email)) {
        Add-FieldError $errors 'email' 'That does not look like a valid email address. Example: juan@example.com'
    }
    else {
        $existing = Get-UserByEmail $values.email
        if ($Mode -eq 'register' -and $null -ne $existing) {
            Add-FieldError $errors 'email' 'An account with this email address already exists. Please sign in instead.'
        }
        if ($Mode -eq 'profile' -and $null -ne $existing -and $existing.id -ne $values.userId) {
            Add-FieldError $errors 'email' 'That email address is already used by another account.'
        }
    }

    # --- optional phone -------------------------------------------------
    if (-not [string]::IsNullOrWhiteSpace($values.phone) -and -not (Test-PhoneNumber $values.phone)) {
        Add-FieldError $errors 'phone' 'Please enter a valid phone number (7 to 15 digits), or leave it blank.'
    }

    # --- optional address ------------------------------------------------
    if ($values.address.Length -gt 160) {
        Add-FieldError $errors 'address' 'Your address must be 160 characters or fewer.'
    }

    return @{ Errors = $errors; Values = $values }
}

function Validate-LoginInput {
    param([hashtable]$Body)

    $errors = @{}
    $values = @{
        email    = (Get-FormValue -Body $Body -Name 'email')
        password = [string]$(if ($Body.ContainsKey('password')) { $Body['password'] } else { '' })
        next     = (Get-FormValue -Body $Body -Name 'next')
    }

    if ([string]::IsNullOrWhiteSpace($values.email)) {
        Add-FieldError $errors 'email' 'Please enter your email address.'
    }
    if ([string]::IsNullOrWhiteSpace([string]$values.password)) {
        Add-FieldError $errors 'password' 'Please enter your password.'
    }
    return @{ Errors = $errors; Values = $values }
}

function Validate-ComplaintInput {
    param([hashtable]$Body)

    $errors = @{}
    $values = @{
        title       = (Get-FormValue -Body $Body -Name 'title')
        category    = (Get-FormValue -Body $Body -Name 'category')
        priority    = (Get-FormValue -Body $Body -Name 'priority')
        location    = (Get-FormValue -Body $Body -Name 'location')
        description = (Get-FormValue -Body $Body -Name 'description')
    }

    # --- title ----------------------------------------------------------
    if ([string]::IsNullOrWhiteSpace($values.title)) {
        Add-FieldError $errors 'title' 'Please give your report a short title.'
    }
    elseif ($values.title.Length -lt 5) {
        Add-FieldError $errors 'title' 'The title must be at least 5 characters long.'
    }
    elseif ($values.title.Length -gt 120) {
        Add-FieldError $errors 'title' 'The title must be 120 characters or fewer.'
    }

    # --- category (must be one of the allowed values) --------------------
    if ([string]::IsNullOrWhiteSpace($values.category)) {
        Add-FieldError $errors 'category' 'Please choose a category for your report.'
    }
    elseif ($global:Categories.Value -notcontains $values.category) {
        Add-FieldError $errors 'category' 'Please choose a category from the list provided.'
    }

    # --- priority --------------------------------------------------------
    if ([string]::IsNullOrWhiteSpace($values.priority)) {
        Add-FieldError $errors 'priority' 'Please choose how urgent your concern is.'
    }
    elseif ($global:Priorities.Value -notcontains $values.priority) {
        Add-FieldError $errors 'priority' 'Please choose a priority from the list provided.'
    }

    # --- location ---------------------------------------------------------
    if ([string]::IsNullOrWhiteSpace($values.location)) {
        Add-FieldError $errors 'location' 'Please tell us where the problem is located (purok, street or landmark).'
    }
    elseif ($values.location.Length -lt 3) {
        Add-FieldError $errors 'location' 'Please describe the location in a little more detail.'
    }
    elseif ($values.location.Length -gt 140) {
        Add-FieldError $errors 'location' 'The location must be 140 characters or fewer.'
    }

    # --- description ------------------------------------------------------
    if ([string]::IsNullOrWhiteSpace($values.description)) {
        Add-FieldError $errors 'description' 'Please describe your concern so the barangay can act on it.'
    }
    elseif ($values.description.Length -lt 20) {
        Add-FieldError $errors 'description' 'Please add a bit more detail (at least 20 characters).'
    }
    elseif ($values.description.Length -gt 2000) {
        Add-FieldError $errors 'description' 'The description must be 2,000 characters or fewer.'
    }

    # --- admin-only notes -------------------------------------------------
    if ($Body.ContainsKey('adminNotes')) {
        $notes = Get-FormValue -Body $Body -Name 'adminNotes'
        if ($notes.Length -gt 1000) {
            Add-FieldError $errors 'adminNotes' 'Notes must be 1,000 characters or fewer.'
        }
        $values['adminNotes'] = $notes
    }

    return @{ Errors = $errors; Values = $values }
}

