function Get-PriorityTone {
    param([string]$Priority)
    switch ($Priority) {
        'Urgent' { return 'danger' }
        'High'   { return 'warning' }
        'Medium' { return 'info' }
        default  { return 'neutral' }
    }
}

function Get-StatusTone {
    param([string]$Status)
    switch ($Status) {
        'Resolved'  { return 'success' }
        'In Review' { return 'info' }
        'Rejected'  { return 'muted' }
        default     { return 'warning' }
    }
}

