        $out += '<p class="section-eyebrow">' + (HtmlEncode $Eyebrow) + '</p>'
    }
    $out += '<h2 class="section-title">' + (HtmlEncode $Heading) + '</h2>'
    if (-not [string]::IsNullOrWhiteSpace($Sub)) {
