.container-narrow { max-width: 820px; }
.section { padding: 44px 0; }
.section-narrow { padding: 32px 0 56px; max-width: 940px; margin: 0 auto; padding-left: 20px; padding-right: 20px; }
.section-alt { background: var(--white); border-top: 1px solid var(--gray-200); border-bottom: 1px solid var(--gray-200); }
.main { min-height: 60vh; }

.skip-link {
  position: absolute; left: -9999px; top: 0; z-index: 200;
  background: var(--green-800); color: #fff; padding: 12px 20px; border-radius: 0 0 var(--radius) 0;
}
.skip-link:focus { left: 0; color: #fff; text-decoration: none; }

/* ------------------------------------------------------------------ header */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: saturate(160%) blur(10px);
  border-bottom: 1px solid var(--gray-200);
}
.header-inner { display: flex; align-items: center; gap: 16px; min-height: var(--header-h); }

.brand { display: flex; align-items: center; gap: 12px; color: inherit; text-decoration: none; flex-shrink: 0; }
.brand:hover { text-decoration: none; }
.brand-mark { width: 44px; height: 44px; flex-shrink: 0; }
.brand-mark-lg { width: 64px; height: 64px; margin: 0 auto 12px; }
.brand-text { display: flex; flex-direction: column; line-height: 1.2; }
.brand-text strong { font-size: 1rem; color: var(--green-800); letter-spacing: -0.01em; }
.brand-text small { font-size: 0.72rem; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.06em; }

.nav-toggle {
  margin-left: auto;
  display: inline-flex; align-items: center; gap: 9px;
  background: var(--gray-100); border: 1px solid var(--gray-300);
  border-radius: var(--radius-sm); padding: 9px 13px;
  font-size: 0.9rem; font-weight: 600; color: var(--gray-700); cursor: pointer;
}
.nav-toggle:hover { background: var(--gray-200); }
.nav-toggle-bars { display: inline-flex; flex-direction: column; gap: 4px; width: 18px; }
.nav-toggle-bars span { display: block; height: 2px; background: currentColor; border-radius: 2px; transition: transform .2s ease, opacity .2s ease; }
.nav-toggle[aria-expanded="true"] .nav-toggle-bars span:nth-child(1) { transform: translateY(6px) rotate(45deg); }
.nav-toggle[aria-expanded="true"] .nav-toggle-bars span:nth-child(2) { opacity: 0; }
.nav-toggle[aria-expanded="true"] .nav-toggle-bars span:nth-child(3) { transform: translateY(-6px) rotate(-45deg); }

.site-nav {
  display: none;
  position: absolute; left: 0; right: 0; top: 100%;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  box-shadow: var(--shadow-md);
  padding: 14px 20px 20px;
  flex-direction: column; gap: 6px;
}
.site-nav.is-open { display: flex; }
.nav-links { display: flex; flex-direction: column; gap: 2px; }
.nav-links a {
  display: block; padding: 11px 12px; border-radius: var(--radius-sm);
  color: var(--gray-700); font-weight: 600; font-size: 0.95rem;
}
.nav-links a:hover { background: var(--gray-100); text-decoration: none; color: var(--green-800); }
.nav-links a.is-active { background: var(--green-050); color: var(--green-800); }
.nav-actions { display: flex; flex-direction: column; gap: 10px; margin-top: 10px; padding-top: 14px; border-top: 1px solid var(--gray-200); }
.nav-actions .btn { width: 100%; }

.user-chip { display: flex; align-items: center; gap: 10px; }
.user-chip-text { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.user-chip-text strong { font-size: 0.9rem; color: var(--gray-900); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.inline-form { display: inline-flex; margin: 0; }

@media (min-width: 940px) {
  .nav-toggle { display: none; }
  .site-nav {
    display: flex !important; position: static; flex-direction: row; align-items: center;
    gap: 18px; margin-left: auto; padding: 0; border: 0; box-shadow: none; background: none;
  }
  .nav-links { flex-direction: row; gap: 2px; }
  .nav-links a { padding: 8px 12px; font-size: 0.9rem; }
  .nav-actions { flex-direction: row; align-items: center; gap: 12px; margin: 0; padding: 0; border: 0; }
  .nav-actions .btn { width: auto; }
}

/* ----------------------------------------------------------------- buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 11px 20px; border-radius: var(--radius-pill);
  font-weight: 650; font-size: 0.925rem; line-height: 1.2;
  border: 1.5px solid transparent; cursor: pointer;
  text-decoration: none; text-align: center;
  transition: background-color .16s ease, color .16s ease, border-color .16s ease, box-shadow .16s ease, transform .08s ease;
  white-space: nowrap;
}
.btn:hover { text-decoration: none; }
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--green-700); color: #fff; box-shadow: var(--shadow-sm); }
.btn-primary:hover { background: var(--green-600); color: #fff; box-shadow: var(--shadow); }
.btn-outline { background: var(--white); color: var(--green-800); border-color: var(--gray-300); }
.btn-outline:hover { border-color: var(--green-600); background: var(--green-050); color: var(--green-800); }
.btn-ghost { background: transparent; color: var(--gray-700); border-color: var(--gray-300); }
.btn-ghost:hover { background: var(--gray-100); color: var(--gray-900); }
.btn-danger { background: var(--red-600); color: #fff; }
.btn-danger:hover { background: var(--red-700); color: #fff; }
.btn-danger-ghost { background: transparent; color: var(--red-700); border-color: #f3c1c1; }
.btn-danger-ghost:hover { background: var(--red-100); color: var(--red-700); }
.btn-light { background: var(--white); color: var(--green-800); box-shadow: var(--shadow-sm); }
.btn-light:hover { background: var(--green-050); color: var(--green-900); }
.btn-ghost-light { background: rgba(255,255,255,.12); color: #fff; border-color: rgba(255,255,255,.55); }
.btn-ghost-light:hover { background: rgba(255,255,255,.22); color: #fff; }
.btn-block { width: 100%; }
.btn-lg { padding: 14px 26px; font-size: 1rem; }
.btn-sm { padding: 8px 15px; font-size: 0.85rem; }
.btn-xs { padding: 6px 11px; font-size: 0.78rem; border-radius: var(--radius-pill); }

/* ------------------------------------------------------------------- hero */
.hero {
  background:
    radial-gradient(1100px 420px at 88% -12%, #e7f6ee 0%, rgba(231,246,238,0) 62%),
    linear-gradient(180deg, #f7fcfa 0%, #eef7f2 100%);
  border-bottom: 1px solid var(--gray-200);
  padding: 40px 0 48px;
}
.hero-grid { display: grid; gap: 30px; align-items: center; }
.hero-eyebrow {
  display: inline-block; font-size: 0.74rem; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--green-700);
  background: var(--green-100); padding: 6px 12px; border-radius: var(--radius-pill);
  margin-bottom: 16px;
}
.hero-title { font-size: 2.1rem; letter-spacing: -0.03em; margin-bottom: 16px; }
.hero-text { font-size: 1.05rem; color: var(--gray-600); max-width: 55ch; margin-bottom: 24px; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 16px; }
.hero-note { font-size: 0.875rem; color: var(--gray-500); margin: 0; }
.hero-art { display: flex; justify-content: center; }
.hero-art img { width: 100%; max-width: 520px; }

.welcome-strip {
  display: flex; flex-wrap: wrap; align-items: center; gap: 14px;
  background: var(--green-800); color: #fff; padding: 14px 18px;
  border-radius: var(--radius); margin: 22px auto 0; max-width: var(--container);
}
.welcome-strip p { margin: 0; flex: 1 1 220px; font-size: 0.95rem; }
.welcome-icon { font-size: 1.35rem; }
.welcome-strip .btn-primary { background: var(--white); color: var(--green-800); }
.welcome-strip .btn-primary:hover { background: var(--green-050); }

@media (min-width: 900px) {
  .hero { padding: 68px 0 76px; }
  .hero-grid { grid-template-columns: 1.05fr 0.95fr; gap: 48px; }
  .hero-title { font-size: 3rem; }
  .hero-text { font-size: 1.12rem; }
}

/* ---------------------------------------------------------- commit strip */
.commit-strip { background: var(--white); border-bottom: 1px solid var(--gray-200); padding: 22px 0; }
.commit-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; text-align: center; }
.commit-value { font-size: 1.6rem; font-weight: 800; color: var(--green-700); margin: 0; line-height: 1.1; }
.commit-label { font-size: 0.8rem; color: var(--gray-500); margin: 3px 0 0; text-transform: uppercase; letter-spacing: .05em; }
@media (min-width: 720px) { .commit-grid { grid-template-columns: repeat(4, 1fr); } }

/* ------------------------------------------------------ section headings */
.section-eyebrow {
  font-size: 0.74rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--green-600); margin: 0 0 8px;
}
.section-title { font-size: 1.75rem; letter-spacing: -0.025em; margin-bottom: 10px; }
.section-title-sm { font-size: 1.25rem; }
.section-sub { color: var(--gray-600); max-width: 62ch; margin: 0; }
.section-head { margin-bottom: 30px; }
.section-head-center { text-align: center; }
.section-head-center .section-sub { margin-left: auto; margin-right: auto; }
.section-cta { text-align: center; margin-top: 32px; }
.section-cta-note { display: block; margin-top: 10px; font-size: 0.85rem; color: var(--gray-500); }

/* --------------------------------------------------------- service cards */
.service-grid { display: grid; grid-template-columns: 1fr; gap: 16px; }
@media (min-width: 620px) { .service-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 980px) { .service-grid { grid-template-columns: repeat(4, 1fr); } }

.service-card {
  position: relative; background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 22px 20px 20px; box-shadow: var(--shadow-sm);
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.service-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); border-color: var(--green-500); }
.service-icon {
  width: 62px; height: 62px; border-radius: 16px; background: var(--green-050);
  display: flex; align-items: center; justify-content: center; margin-bottom: 14px;
  border: 1px solid var(--green-100);
}
.service-icon img { width: 44px; height: 44px; }
.service-title { font-size: 1rem; margin-bottom: 6px; }
.service-text { font-size: 0.875rem; color: var(--gray-600); margin: 0; }
.service-step { position: absolute; top: 16px; right: 16px; margin: 0; }
.service-num {
  display: inline-flex; align-items: center; justify-content: center;
  width: 24px; height: 24px; border-radius: 50%;
  background: var(--gray-100); color: var(--gray-500); font-size: 0.72rem; font-weight: 700;
}

/* ---------------------------------------------------------------- steps */
.steps-grid { list-style: none; padding: 0; margin: 0; display: grid; gap: 16px; counter-reset: step; }
@media (min-width: 700px) { .steps-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1000px) { .steps-grid { grid-template-columns: repeat(4, 1fr); } }
.step-card {
  background: var(--gray-050); border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 24px 20px; position: relative;
}
.step-num {
  display: inline-flex; align-items: center; justify-content: center;
  width: 40px; height: 40px; border-radius: 12px; margin-bottom: 14px;
  background: var(--green-700); color: #fff; font-weight: 800; font-size: 1.05rem;
}
.step-title { font-size: 1rem; margin-bottom: 6px; }
.step-text { font-size: 0.875rem; color: var(--gray-600); margin: 0; }

.mini-steps { padding-left: 1.1rem; margin: 0; font-size: 0.875rem; color: var(--gray-600); }
.mini-steps li { margin-bottom: 7px; }

/* -------------------------------------------------------- about / contact */
.about-grid { display: grid; gap: 30px; align-items: center; }
@media (min-width: 920px) { .about-grid { grid-template-columns: 0.9fr 1.1fr; gap: 52px; } }
.about-art img { width: 100%; }
.about-copy .section-head { margin-bottom: 20px; }

.check-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 14px; }
.check-list li { display: flex; gap: 12px; align-items: flex-start; }
.check-list p { margin: 2px 0 0; font-size: 0.875rem; color: var(--gray-600); }
.check-icon {
  flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;
  width: 24px; height: 24px; border-radius: 50%;
  background: var(--green-100); color: var(--green-700); font-weight: 800; font-size: 0.78rem;
}

.contact-grid { display: grid; gap: 26px; }
@media (min-width: 860px) { .contact-grid { grid-template-columns: 1.15fr 0.85fr; gap: 40px; } }
.detail-list-card {
  margin: 0; background: var(--gray-050); border: 1px solid var(--gray-200);
  border-radius: var(--radius); padding: 6px 18px;
}
.contact-card {
  background: var(--green-800); color: #fff; border-radius: var(--radius-lg);
  padding: 26px 24px; box-shadow: var(--shadow-md); align-self: start;
}
.contact-title { color: #fff; font-size: 1.15rem; }
.contact-note { font-size: 0.85rem; color: rgba(255,255,255,.75); }
.contact-list { list-style: none; padding: 0; margin: 0; }
.contact-list li {
  display: flex; justify-content: space-between; align-items: baseline; gap: 12px;
  padding: 11px 0; border-bottom: 1px solid rgba(255,255,255,.14); font-size: 0.9rem;
}
.contact-list li:last-child { border-bottom: 0; }
.contact-list span { color: rgba(255,255,255,.8); }
.contact-list strong { color: #fff; font-family: var(--mono); font-size: 0.95rem; }

/* ------------------------------------------------------------------- FAQ */
.faq-list { display: grid; gap: 10px; }
.faq-item {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow-sm);
}
.faq-question {
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  padding: 16px 18px; cursor: pointer; font-weight: 650; color: var(--gray-900);
  list-style: none; font-size: 0.95rem;
}
.faq-question::-webkit-details-marker { display: none; }
.faq-question:hover { background: var(--green-050); }
.faq-plus { position: relative; flex-shrink: 0; width: 18px; height: 18px; }
.faq-plus::before, .faq-plus::after {
  content: ""; position: absolute; background: var(--green-700); border-radius: 2px;
  transition: transform .2s ease;
}
.faq-plus::before { left: 0; top: 8px; width: 18px; height: 2px; }
.faq-plus::after  { left: 8px; top: 0; width: 2px; height: 18px; }
.faq-item[open] .faq-plus::after { transform: scaleY(0); }
.faq-answer { padding: 0 18px 16px; }
.faq-answer p { margin: 0; font-size: 0.9rem; color: var(--gray-600); }

/* -------------------------------------------------------------- final CTA */
.final-cta { background: linear-gradient(135deg, var(--green-800) 0%, var(--green-600) 100%); padding: 46px 0; }
.final-cta-inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 22px; }
.final-cta-title { color: #fff; font-size: 1.7rem; margin-bottom: 6px; letter-spacing: -0.02em; }
.final-cta-text { color: rgba(255,255,255,.85); margin: 0; max-width: 52ch; }
.final-cta-actions { display: flex; flex-wrap: wrap; gap: 12px; }
@media (min-width: 900px) { .final-cta { padding: 60px 0; } .final-cta-title { font-size: 2.1rem; } }

/* ----------------------------------------------------------------- footer */
.site-footer { background: var(--navy-900); color: rgba(255,255,255,.72); padding: 40px 0 0; }
.footer-grid { display: grid; gap: 28px; padding-bottom: 30px; }
@media (min-width: 700px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 980px) { .footer-grid { grid-template-columns: 1.4fr 1fr 1fr 0.8fr; } }
.footer-brand .brand-mark { margin-bottom: 12px; }
.footer-name { color: #fff; font-weight: 700; font-size: 1.05rem; margin: 0 0 6px; }
.footer-tagline { font-size: 0.85rem; margin: 0 0 6px; max-width: 42ch; }
.footer-col h3 { color: #fff; font-size: 0.8rem; text-transform: uppercase; letter-spacing: .08em; margin-bottom: 12px; }
.footer-list { list-style: none; padding: 0; margin: 0 0 16px; font-size: 0.875rem; }
.footer-list li { margin-bottom: 7px; }
.footer-list a { color: rgba(255,255,255,.82); }
.footer-list a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.14); padding: 16px 0 22px;
  display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px;
  font-size: 0.8rem; color: rgba(255,255,255,.6);
}
.footer-bottom p { margin: 0; }

/* ------------------------------------------------------------- page intro */
.page-intro { margin-bottom: 24px; }
.page-eyebrow { font-size: 0.74rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--green-600); margin: 0 0 8px; }
.page-title { font-size: 1.85rem; letter-spacing: -0.03em; margin-bottom: 8px; }
.page-sub { color: var(--gray-600); max-width: 70ch; margin: 0; }
.page-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
@media (min-width: 760px) { .page-title { font-size: 2.25rem; } }

.breadcrumb { margin-bottom: 16px; font-size: 0.875rem; }
.breadcrumb a { font-weight: 600; }

/* -------------------------------------------------------------- stat tiles */
.stat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; margin-bottom: 24px; }
@media (min-width: 820px) { .stat-grid-4 { grid-template-columns: repeat(4, 1fr); } }
.stat-tile {
  background: var(--white); border: 1px solid var(--gray-200); border-left: 4px solid var(--gray-300);
  border-radius: var(--radius); padding: 16px 18px; box-shadow: var(--shadow-sm);
}
.stat-brand   { border-left-color: var(--green-700); }
.stat-warning { border-left-color: var(--amber-500); }
.stat-info    { border-left-color: var(--blue-600); }
.stat-success { border-left-color: var(--green-500); }
.stat-value { font-size: 1.9rem; font-weight: 800; line-height: 1.05; margin: 0; color: var(--gray-900); letter-spacing: -0.03em; }
.stat-label { font-size: 0.78rem; font-weight: 650; color: var(--gray-700); margin: 4px 0 0; text-transform: uppercase; letter-spacing: .05em; }
.stat-hint { font-size: 0.78rem; color: var(--gray-500); margin: 3px 0 0; }

/* ------------------------------------------------------------ filter bar */
.filter-bar {
  display: grid; gap: 14px; background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius); padding: 18px; margin-bottom: 16px; box-shadow: var(--shadow-sm);
}
@media (min-width: 780px) { .filter-bar { grid-template-columns: 1.6fr repeat(3, 1fr) auto; align-items: end; } }
.filter-actions { display: flex; gap: 8px; }
.result-count { font-size: 0.875rem; color: var(--gray-500); margin-bottom: 16px; }

/* -------------------------------------------------------------- form bits */
.field { margin-bottom: 16px; }
.field:last-child { margin-bottom: 0; }
.field label, .field-head label {
  display: block; font-weight: 650; font-size: 0.875rem; color: var(--gray-900); margin-bottom: 6px;
}
.field-head { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }
.field-hint { font-size: 0.78rem; color: var(--gray-500); margin: 6px 0 0; }
.field-hint-link { font-size: 0.78rem; font-weight: 600; }
.req { color: var(--red-600); }
.optional { font-size: 0.72rem; font-weight: 500; color: var(--gray-400); text-transform: uppercase; letter-spacing: .05em; }

input[type="text"], input[type="email"], input[type="password"], input[type="search"],
input[type="tel"], select, textarea {
  width: 100%; padding: 11px 13px; background: var(--white);
  border: 1.5px solid var(--gray-300); border-radius: var(--radius-sm);
  font-size: 0.95rem; color: var(--gray-900);
  transition: border-color .15s ease, box-shadow .15s ease;
}
textarea { resize: vertical; min-height: 96px; line-height: 1.6; }
input:hover, select:hover, textarea:hover { border-color: var(--gray-400); }
input:focus, select:focus, textarea:focus {
  outline: none; border-color: var(--green-600);
  box-shadow: 0 0 0 3px rgba(23, 105, 76, 0.14);
}
input::placeholder, textarea::placeholder { color: var(--gray-400); }
select {
  appearance: none; -webkit-appearance: none; padding-right: 38px; cursor: pointer;
  background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23667085'%3E%3Cpath d='M4.5 6.5 8 10l3.5-3.5z'/%3E%3C/svg%3E");
  background-repeat: no-repeat; background-position: right 12px center; background-size: 16px;
}
.is-invalid, input.is-invalid, select.is-invalid, textarea.is-invalid {
  border-color: var(--red-600); background-color: #fffafa;
}
.is-invalid:focus, input.is-invalid:focus, select.is-invalid:focus, textarea.is-invalid:focus {
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.14);
}
.field-error { color: var(--red-700); font-size: 0.8rem; font-weight: 600; margin: 6px 0 0; }
.field-error[hidden] { display: none; }

.password-field { position: relative; display: flex; }
.password-field input { padding-right: 68px; }
.password-toggle {
  position: absolute; right: 6px; top: 50%; transform: translateY(-50%);
  background: var(--gray-100); border: 0; border-radius: 6px;
  padding: 6px 10px; font-size: 0.78rem; font-weight: 650; color: var(--gray-600); cursor: pointer;
}
.password-toggle:hover { background: var(--gray-200); color: var(--gray-900); }

.strength { margin-top: 10px; }
.strength-bar { height: 6px; background: var(--gray-200); border-radius: var(--radius-pill); overflow: hidden; }
.strength-bar span { display: block; height: 100%; width: 0; background: var(--red-600); transition: width .25s ease, background-color .25s ease; border-radius: var(--radius-pill); }
.strength.is-weak span { background: var(--red-600); }
.strength.is-fair span { background: var(--amber-500); }
.strength.is-good span { background: var(--blue-600); }
.strength.is-strong span { background: var(--green-500); }
.strength-label { font-size: 0.78rem; font-weight: 600; color: var(--gray-600); margin: 5px 0 0; }

.rule-list { list-style: none; padding: 0; margin: 10px 0 0; display: grid; gap: 3px; font-size: 0.78rem; color: var(--gray-500); }
.rule-list li::before { content: "○ "; color: var(--gray-400); }
.rule-list li.is-met { color: var(--green-700); }
.rule-list li.is-met::before { content: "\2713 "; color: var(--green-600); font-weight: 800; }

.checkbox { display: flex; gap: 10px; align-items: flex-start; font-size: 0.85rem; color: var(--gray-600); margin-bottom: 18px; cursor: pointer; }
.checkbox input { width: 18px; height: 18px; margin-top: 2px; flex-shrink: 0; accent-color: var(--green-700); }

.form-stack { display: flex; flex-direction: column; }
.form-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 6px; }
.form-actions-split { justify-content: space-between; align-items: center; }
.field-grid { display: grid; gap: 16px; }
@media (min-width: 620px) { .field-grid { grid-template-columns: 1fr 1fr; } }
.char-count { text-align: right; }

/* ------------------------------------------------------------------ cards */
.card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-lg);
  padding: 22px; box-shadow: var(--shadow-sm); margin-bottom: 18px;
}
.card:last-child { margin-bottom: 0; }
.card-quiet { background: var(--gray-050); box-shadow: none; }
.card-flush { padding: 6px 22px 18px; }
.card-danger { border-color: #f5c6c6; border-top: 4px solid var(--red-600); background: #fffafa; }
.card-status { border-color: var(--green-500); background: var(--green-050); }
.card-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 16px; }
.card-title { font-size: 1rem; margin: 0; }
.card-text { font-size: 0.875rem; color: var(--gray-600); }
.card-note { font-size: 0.78rem; color: var(--gray-500); margin: 12px 0 0; }
.stack-actions { display: flex; flex-direction: column; gap: 9px; }
.stack-actions .btn { width: 100%; }
.side-stack { display: grid; gap: 0; align-content: start; }

.detail-list { margin: 0; display: grid; gap: 0; }
.detail-list > div {
  display: flex; justify-content: space-between; align-items: baseline; gap: 14px;
  padding: 10px 0; border-bottom: 1px solid var(--gray-200);
}
.detail-list > div:last-child { border-bottom: 0; }
.detail-list dt { font-size: 0.8rem; font-weight: 600; color: var(--gray-500); text-transform: uppercase; letter-spacing: .04em; margin: 0; }
.detail-list dd { margin: 0; font-size: 0.9rem; color: var(--gray-900); font-weight: 600; text-align: right; word-break: break-word; }
.detail-list-grid { display: grid; grid-template-columns: 1fr; gap: 0; margin-top: 20px; padding-top: 8px; border-top: 1px solid var(--gray-200); }
@media (min-width: 620px) { .detail-list-grid { grid-template-columns: 1fr 1fr; column-gap: 30px; } }

.hint-list { list-style: none; padding: 0; margin: 0; font-size: 0.8rem; color: var(--gray-600); display: grid; gap: 7px; }
.hint-list strong { color: var(--gray-900); }

.reporter-preview {
  background: var(--gray-050); border: 1px dashed var(--gray-300); border-radius: var(--radius-sm);
  padding: 14px 16px; margin-bottom: 18px;
}
.reporter-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: .06em; color: var(--gray-500); margin: 0 0 4px; font-weight: 700; }
.reporter-name { font-weight: 700; color: var(--gray-900); margin: 0; font-size: 0.95rem; }
.reporter-meta { font-size: 0.8rem; color: var(--gray-500); margin: 0; }

.form-layout { display: grid; gap: 0; }
@media (min-width: 980px) { .form-layout { grid-template-columns: 1.45fr 0.9fr; gap: 26px; align-items: start; } }

/* ------------------------------------------------------------- badges/pills */
.badge {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 4px 10px; border-radius: var(--radius-pill);
  font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .05em;
  border: 1px solid transparent; white-space: nowrap;
}
.badge-danger  { background: var(--red-100); color: var(--red-700); border-color: #fbc5c5; }
.badge-warning { background: var(--amber-100); color: var(--amber-600); border-color: #fde1a4; }
.badge-info    { background: var(--blue-100); color: var(--blue-600); border-color: #bfd6fb; }
.badge-success { background: var(--green-100); color: var(--green-700); border-color: #b8e2d0; }
.badge-neutral { background: var(--gray-100); color: var(--gray-600); border-color: var(--gray-300); }
.badge-muted   { background: var(--gray-100); color: var(--gray-500); border-color: var(--gray-300); }

.role-pill { display: inline-block; padding: 3px 9px; border-radius: var(--radius-pill); font-size: 0.68rem; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; }
.role-admin { background: var(--navy-900); color: #fff; }
.role-resident { background: var(--green-100); color: var(--green-700); }

.avatar {
  display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0;
  width: 36px; height: 36px; border-radius: 50%;
  font-size: 0.78rem; font-weight: 800; letter-spacing: .02em;
}
.badge-admin { background: var(--navy-900); color: #fff; }
.badge-resident { background: var(--green-100); color: var(--green-700); }

/* -------------------------------------------------------------- complaint rows */
.row-list { display: grid; gap: 12px; }
.row-card {
  display: flex; flex-wrap: wrap; gap: 14px; justify-content: space-between; align-items: flex-start;
  background: var(--white); border: 1px solid var(--gray-200); border-left: 4px solid var(--gray-300);
  border-radius: var(--radius); padding: 16px 18px; box-shadow: var(--shadow-sm);
  transition: box-shadow .16s ease, border-color .16s ease;
}
.row-card:hover { box-shadow: var(--shadow-md); }
.row-card[data-priority="danger"]  { border-left-color: var(--red-600); }
.row-card[data-priority="warning"] { border-left-color: var(--amber-500); }
.row-card[data-priority="info"]    { border-left-color: var(--blue-600); }
.row-card[data-priority="neutral"]  { border-left-color: var(--gray-400); }
.row-main { flex: 1 1 320px; min-width: 0; }
.row-badges { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.row-title { font-size: 1.02rem; margin: 0 0 8px; }
.row-title a { color: var(--gray-900); }
.row-title a:hover { color: var(--green-700); }
.row-desc { font-size: 0.875rem; color: var(--gray-600); margin: 8px 0 0; }
.row-note {
  font-size: 0.8rem; color: var(--gray-600); margin: 10px 0 0;
  background: var(--green-050); border-left: 3px solid var(--green-500);
  padding: 8px 12px; border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}
.row-meta { display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 0.78rem; color: var(--gray-600); }
.meta-item { display: inline-flex; gap: 5px; }
.meta-label { color: var(--gray-400); text-transform: uppercase; letter-spacing: .04em; font-size: 0.68rem; font-weight: 700; align-self: center; }
.row-side { flex: 0 0 auto; align-self: center; }

/* -------------------------------------------------------------- detail page */
.detail-layout { display: grid; gap: 0; }
@media (min-width: 980px) { .detail-layout { grid-template-columns: 1.5fr 0.85fr; gap: 26px; align-items: start; } }
.detail-card { padding: 26px 24px; }
.detail-head { padding-bottom: 18px; border-bottom: 1px solid var(--gray-200); margin-bottom: 20px; }
.detail-title { font-size: 1.55rem; letter-spacing: -0.025em; margin: 10px 0 6px; }
.detail-category { color: var(--green-700); font-weight: 600; font-size: 0.9rem; margin: 0; }
.detail-body { margin-bottom: 8px; }
.detail-section-title { font-size: 0.78rem; text-transform: uppercase; letter-spacing: .08em; color: var(--gray-500); margin-bottom: 8px; }
.detail-text { white-space: pre-wrap; color: var(--gray-700); }
.admin-note { background: var(--green-050); border: 1px solid var(--green-100); border-radius: var(--radius); padding: 14px 16px; margin: 16px 0 0; }
.admin-note-label { font-size: 0.7rem; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; color: var(--green-700); margin: 0 0 4px; }
.admin-note-text { margin: 0; font-size: 0.9rem; color: var(--gray-700); white-space: pre-wrap; }

.detail-timeline { margin-top: 24px; padding-top: 18px; border-top: 1px solid var(--gray-200); }
.steps { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 12px; }
.step { display: flex; align-items: flex-start; gap: 9px; flex: 1 1 150px; }
.step-dot { width: 14px; height: 14px; border-radius: 50%; border: 3px solid var(--gray-300); background: var(--white); margin-top: 4px; flex-shrink: 0; }
.step-body { display: flex; flex-direction: column; }
.step-body strong { font-size: 0.85rem; color: var(--gray-600); }
.step-body small { font-size: 0.72rem; color: var(--gray-400); }
.step-done .step-dot { background: var(--green-600); border-color: var(--green-600); }
.step-done .step-body strong { color: var(--green-800); }
.step-current .step-dot { background: var(--white); border-color: var(--amber-500); box-shadow: 0 0 0 4px var(--amber-100); }
.step-current .step-body strong { color: var(--amber-600); }
.step-rejected .step-dot { background: var(--red-600); border-color: var(--red-600); }
.step-rejected .step-body strong { color: var(--red-700); }

/* ------------------------------------------------------------ danger panel */
.danger-head { display: flex; gap: 14px; align-items: flex-start; margin-bottom: 18px; }
.danger-icon { font-size: 1.6rem; line-height: 1; }
.danger-title { font-size: 1.1rem; margin: 0 0 4px; color: var(--red-700); }
.danger-text { margin: 0; font-size: 0.875rem; color: var(--gray-600); }

/* --------------------------------------------------------------- pagination */
.pagination { margin-top: 24px; }
.pagination ul { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; }
.page-item a, .page-item span {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 40px; height: 40px; padding: 0 12px;
  border-radius: var(--radius-sm); border: 1px solid var(--gray-300);
  background: var(--white); font-size: 0.875rem; font-weight: 600; color: var(--gray-700);
}
.page-item a:hover { border-color: var(--green-600); color: var(--green-800); text-decoration: none; background: var(--green-050); }
.page-item.is-current span { background: var(--green-700); border-color: var(--green-700); color: #fff; }
.page-item.is-disabled a { opacity: .45; pointer-events: none; }

/* --------------------------------------------------------------- empty state */
.empty-state {
  text-align: center; background: var(--white); border: 2px dashed var(--gray-300);
  border-radius: var(--radius-lg); padding: 44px 24px;
}
.empty-icon { font-size: 2.2rem; display: block; margin-bottom: 10px; }
.empty-title { font-size: 1.1rem; margin-bottom: 6px; }
.empty-text { font-size: 0.9rem; color: var(--gray-600); max-width: 46ch; margin: 0 auto 18px; }

/* ------------------------------------------------------------------- table */
.table-wrap {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-lg);
  overflow: hidden; box-shadow: var(--shadow-sm);
}
.table { font-size: 0.875rem; }
.table thead th {
  background: var(--gray-100); color: var(--gray-600); font-size: 0.72rem;
  text-transform: uppercase; letter-spacing: .06em; font-weight: 800;
  text-align: left; padding: 12px 16px; white-space: nowrap; border-bottom: 1px solid var(--gray-200);
}
.table tbody td, .table tbody th { padding: 14px 16px; border-bottom: 1px solid var(--gray-200); vertical-align: top; text-align: left; font-weight: 400; }
.table tbody tr:last-child td, .table tbody tr:last-child th { border-bottom: 0; }
.table tbody tr:hover { background: var(--gray-050); }
.table tbody tr.is-inactive { opacity: .68; }
.table-sub { color: var(--gray-500); font-size: 0.78rem; }
.table-contact { min-width: 200px; word-break: break-word; }
.cell-user { display: flex; align-items: center; gap: 10px; }
.cell-user-text { font-weight: 650; color: var(--gray-900); }
.row-actions { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.action-note { font-size: 0.75rem; color: var(--gray-400); }
.col-actions { width: 1%; white-space: nowrap; }

/* Collapse the table into stacked cards on phones */
@media (max-width: 720px) {
  .table thead { display: none; }
  .table, .table tbody, .table tr, .table td, .table th { display: block; width: 100%; }
  .table tr {
    border-bottom: 1px solid var(--gray-200); padding: 14px 16px; position: relative;
  }
  .table tbody tr:last-child { border-bottom: 0; }
  .table tbody td, .table tbody th { border: 0; padding: 4px 0; }
  .table tbody td::before, .table tbody th::before {
    content: attr(data-label); display: block;
    font-size: 0.68rem; font-weight: 800; text-transform: uppercase; letter-spacing: .06em;
    color: var(--gray-400); margin-bottom: 2px;
  }
  .table tbody th::before { display: none; }
  .table .col-actions { margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--gray-200); width: 100%; white-space: normal; }
  .table .col-actions::before { margin-bottom: 6px; }
}

/* ------------------------------------------------------------- dashboard bits */
.dashboard-grid { display: grid; gap: 0; }
@media (min-width: 1000px) { .dashboard-grid { grid-template-columns: 1.55fr 0.85fr; gap: 26px; align-items: start; } }
.dash-main .section-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px; margin-bottom: 16px; }
.dash-main .section-head .section-title { margin: 0; }

.bar-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.bar-item { display: grid; grid-template-columns: 1fr auto; gap: 4px 10px; align-items: center; }
.bar-label { font-size: 0.8rem; color: var(--gray-700); font-weight: 600; }
.bar-value { font-size: 0.8rem; font-weight: 800; color: var(--gray-900); }
.bar-track { grid-column: 1 / -1; height: 8px; background: var(--gray-200); border-radius: var(--radius-pill); overflow: hidden; }
.bar-fill { display: block; height: 100%; background: linear-gradient(90deg, var(--green-600), var(--green-500)); border-radius: var(--radius-pill); }

.urgent-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }
.urgent-item a {
  display: flex; align-items: center; gap: 9px; flex-wrap: wrap;
  padding: 11px 13px; border: 1px solid var(--gray-200); border-radius: var(--radius-sm);
  background: var(--white); text-decoration: none;
}
.urgent-item a:hover { border-color: var(--green-500); background: var(--green-050); text-decoration: none; }
.urgent-title { flex: 1 1 130px; font-size: 0.83rem; font-weight: 600; color: var(--gray-900); min-width: 0; }
.urgent-empty { font-size: 0.85rem; color: var(--gray-500); padding: 8px 0; }

/* --------------------------------------------------------------- auth pages */
.auth-shell {
  display: flex; justify-content: center; align-items: flex-start;
  padding: 34px 20px 56px; min-height: calc(100vh - var(--header-h) - 60px);
  background:
    radial-gradient(900px 380px at 50% -10%, #e9f6ef 0%, rgba(233,246,239,0) 60%),
    var(--gray-050);
}
.auth-card {
  width: 100%; max-width: 480px; background: var(--white);
  border: 1px solid var(--gray-200); border-radius: var(--radius-lg);
  padding: 30px 26px; box-shadow: var(--shadow-lg);
}
.auth-card-lg { max-width: 560px; }
.auth-head { text-align: center; margin-bottom: 22px; }
.auth-title { font-size: 1.65rem; margin-bottom: 6px; }
.auth-sub { font-size: 0.9rem; color: var(--gray-600); margin: 0; }
.auth-alt { text-align: center; font-size: 0.875rem; color: var(--gray-600); margin: 20px 0 0; }
.auth-alt a { font-weight: 650; }

.demo-box { margin-top: 24px; padding-top: 20px; border-top: 1px dashed var(--gray-300); }
.demo-title { font-size: 0.72rem; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; color: var(--gray-500); margin: 0 0 10px; }
.demo-table { font-size: 0.78rem; }
.demo-table th { text-align: left; font-size: 0.68rem; text-transform: uppercase; letter-spacing: .05em; color: var(--gray-500); padding-bottom: 6px; }
.demo-table td { padding: 6px 8px 6px 0; border-top: 1px solid var(--gray-200); vertical-align: middle; }
.demo-table code { font-size: 0.72rem; }
.demo-hint { font-size: 0.75rem; color: var(--gray-500); margin: 10px 0 0; }
@media (max-width: 480px) { .demo-table code { font-size: 0.66rem; } }

/* ------------------------------------------------------------ flash/alert */
.flash {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 14px 16px; border-radius: var(--radius); margin: 0 0 20px;
  border: 1px solid transparent; font-size: 0.9rem;
}
.flash p { margin: 0; flex: 1; }
.flash-icon { font-weight: 800; font-size: 1rem; line-height: 1.4; }
.flash-success { background: var(--green-050); border-color: #b8e2d0; color: var(--green-800); }
.flash-error   { background: #fef2f2; border-color: #fbc5c5; color: var(--red-700); }
.flash-warning { background: #fffbeb; border-color: #fde1a4; color: var(--amber-600); }
.flash-info    { background: var(--blue-100); border-color: #bfd6fb; color: var(--blue-600); }
.flash-close { background: none; border: 0; font-size: 1.3rem; line-height: 1; color: inherit; opacity: .55; cursor: pointer; padding: 0 2px; }
.flash-close:hover { opacity: 1; }

.alert { display: flex; gap: 12px; padding: 14px 16px; border-radius: var(--radius); margin-bottom: 20px; font-size: 0.875rem; border: 1px solid transparent; }
.alert-list { margin: 8px 0 0; padding-left: 1.1rem; }
.alert-icon { font-weight: 800; font-size: 1rem; }
.alert-error   { background: #fef2f2; border-color: #fbc5c5; color: var(--red-700); }
.alert-warning { background: #fffbeb; border-color: #fde1a4; color: #7c4a03; }

/* --------------------------------------------------------- error pages */
.error-panel { text-align: center; background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-lg); padding: 48px 26px; box-shadow: var(--shadow-sm); }
.error-code { display: block; font-size: 3.4rem; font-weight: 800; color: var(--green-100); line-height: 1; letter-spacing: -0.04em; }
.error-icon { font-size: 1.9rem; display: block; margin: -18px 0 10px; }
.error-heading { font-size: 1.5rem; margin-bottom: 8px; }
.error-text { color: var(--gray-600); max-width: 50ch; margin: 0 auto 22px; }
.error-actions { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; }

/* --------------------------------------------------------------- responsive */
@media print {
  .site-header, .site-footer, .page-actions, .filter-bar, .row-side, .side-stack, .btn { display: none !important; }
  body { background: #fff; }
  .card, .row-card, .table-wrap { box-shadow: none; border-color: #ccc; }
}

/* ==========================================================================
   Barangay Complaint & Concern Reporting System - front-end behaviour
   Progressive enhancement only: every page still works without JavaScript.
   ========================================================================== */
(function () {
  'use strict';

  /* ------------------------------------------------- mobile navigation --- */
  function initNav() {
    var toggle = document.querySelector('[data-nav-toggle]');
    var panel = document.querySelector('[data-nav-panel]');
    if (!toggle || !panel) return;

    toggle.addEventListener('click', function () {
      var open = panel.classList.toggle('is-open');
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });

    // Close the menu when a link is used, or when tapping outside it.
    panel.addEventListener('click', function (e) {
      if (e.target.tagName === 'A' && window.innerWidth < 940) {
        panel.classList.remove('is-open');
        toggle.setAttribute('aria-expanded', 'false');
      }
    });

    document.addEventListener('click', function (e) {
      if (!panel.classList.contains('is-open')) return;
      if (panel.contains(e.target) || toggle.contains(e.target)) return;
      panel.classList.remove('is-open');
      toggle.setAttribute('aria-expanded', 'false');
    });

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && panel.classList.contains('is-open')) {
        panel.classList.remove('is-open');
        toggle.setAttribute('aria-expanded', 'false');
        toggle.focus();
      }
    });
  }

  /* ---------------------------------------------- password show / hide --- */
  function initPasswordToggles() {
    document.querySelectorAll('[data-password-toggle]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var input = document.getElementById(btn.getAttribute('data-password-toggle'));
        if (!input) return;
        var hidden = input.type === 'password';
        input.type = hidden ? 'text' : 'password';
        btn.textContent = hidden ? 'Hide' : 'Show';
        btn.setAttribute('aria-label', hidden ? 'Hide password' : 'Show password');
      });
    });
  }

  /* -------------------------------------------------- password strength -- */
  function initStrength() {
    var inputs = document.querySelectorAll('[data-strength-input]');
    inputs.forEach(function (input) {
      var form = input.closest('form') || document;
      var meter = form.querySelector('[data-strength-meter]');
      if (!meter) return;
      var fill = meter.querySelector('[data-strength-fill]');
      var label = meter.querySelector('[data-strength-label]');
      var confirm = document.getElementById('passwordConfirm');

      function score(value) {
        if (!value) return 0;
        var s = 0;
        if (value.length >= 8) s++;
        if (value.length >= 12) s++;
        if (/[a-z]/.test(value) && /[A-Z]/.test(value)) s++;
        if (/[0-9]/.test(value)) s++;
        if (/[^A-Za-z0-9]/.test(value)) s++;
        return Math.min(s, 4);
      }

      function update() {
        var value = input.value;
        meter.hidden = value.length === 0;
        var s = score(value);
        meter.classList.remove('is-weak', 'is-fair', 'is-good', 'is-strong');
        var pct = 0;
        if (s === 1) { meter.classList.add('is-weak');   pct = 25; label.textContent = 'Strength: weak'; }
        else if (s === 2) { meter.classList.add('is-fair');  pct = 50; label.textContent = 'Strength: fair'; }
        else if (s === 3) { meter.classList.add('is-good');  pct = 75; label.textContent = 'Strength: good'; }
        else if (s === 4) { meter.classList.add('is-strong'); pct = 100; label.textContent = 'Strength: strong'; }
        else { label.textContent = 'Strength: -'; }
        fill.style.width = pct + '%';

        // Tick off the checklist live.
        form.querySelectorAll('[data-rule]').forEach(function (li) {
          var rule = li.getAttribute('data-rule');
          var ok =
            rule === 'length' ? value.length >= 8 :
            rule === 'letter' ? /[A-Za-z]/.test(value) :
            rule === 'number' ? /[0-9]/.test(value) :
            rule === 'symbol' ? /[^A-Za-z0-9]/.test(value) : false;
          li.classList.toggle('is-met', !!value && ok);
        });

        // Live "do the passwords match" hint.
        if (confirm) {
          var box = form.querySelector('[data-match-error]');
          if (box) {
            var mismatch = confirm.value.length > 0 && confirm.value !== value;
            box.hidden = !mismatch;
            confirm.classList.toggle('is-invalid', mismatch);
          }
        }
      }

      input.addEventListener('input', update);
      if (confirm) confirm.addEventListener('input', update);
      update();
    });
  }

  /* ------------------------------------------------ character counting --- */
  function initCharCount() {
    document.querySelectorAll('[data-char-count]').forEach(function (area) {
      var form = area.closest('form') || document;
      var out = form.querySelector('[data-char-current]');
      if (!out) return;
      var update = function () { out.textContent = String(area.value.length); };
      area.addEventListener('input', update);
      update();
    });
  }

  /* --------------------------------------------------- delete confirms --- */
  function initConfirm() {
    // Inline destructive actions get an extra browser-level confirmation.
    document.querySelectorAll('[data-confirm]').forEach(function (el) {
      el.addEventListener('click', function (e) {
        if (!window.confirm(el.getAttribute('data-confirm'))) {
          e.preventDefault();
          e.stopPropagation();
        }
      });
    });
    document.querySelectorAll('[data-confirm-link]').forEach(function (el) {
      el.addEventListener('click', function (e) {
        if (!window.confirm(el.getAttribute('data-confirm-link'))) e.preventDefault();
      });
    });
  }

  /* ------------------------------------------------------- flash close --- */
  function initFlash() {
    document.querySelectorAll('[data-flash]').forEach(function (flash) {
      var close = flash.querySelector('[data-dismiss-flash]');
      if (close) close.addEventListener('click', function () { flash.remove(); });
    });
  }

  /* --------------------------------------------------- auto-submit form -- */
  function initAutoSubmit() {
    document.querySelectorAll('[data-auto-submit]').forEach(function (form) {
      form.querySelectorAll('select').forEach(function (sel) {
        sel.addEventListener('change', function () { form.submit(); });
      });
    });
  }

  /* ------------------------------------------------- demo credentials ---- */
  var DEMO_ACCOUNTS = {
