$enc  = New-Object System.Text.UTF8Encoding($false)

function Patch-File {
    param([string]$Path, [object[]]$Pairs)

    $t = [IO.File]::ReadAllText($Path)
    $t = $t.Replace("`r`n", "`n")

    $missed = @()
    foreach ($pair in $Pairs) {
        if ($t.Contains($pair[0])) {
            $t = $t.Replace($pair[0], $pair[1])
        } else {
            $missed += $pair[0].Split("`n")[0]
        }
    }
    [IO.File]::WriteAllText($Path, $t, $enc)
    if ($missed.Count -gt 0) {
        Write-Host ("  MISSED in {0}:" -f (Split-Path $Path -Leaf)) -ForegroundColor Yellow
        $missed | ForEach-Object { Write-Host ("    - " + $_) -ForegroundColor Yellow }
    } else {
        Write-Host ("  OK " + (Split-Path $Path -Leaf)) -ForegroundColor Green
    }
}

