function Follow {
    <# Given a response that was a redirect, fetch the page it points at so the
       confirmation message (which travels in the query string) can be asserted. #>
    param($Client, $Response)
    if ($Response.Status -eq 302 -and $Response.Location -ne '') {
        return Invoke-Http $Client $Response.Location
    }
    return $Response
}

input.oldString:
function Follow {
    <# Follows one redirect so confirmation messages (which travel in the query
       string) can be asserted. #>
    param($Client, [string]$Path)
    $r = Invoke-Http $Client $Path
    if ($r.Status -eq 302 -and $r.Location -ne '') {
        return Invoke-Http $Client $r.Location
    }
    return $r
}

