(async () => {
  const results = {};

  // ---- 1. mobile nav toggle -------------------------------------------------
  {
    const f = document.createElement('iframe');
    f.style.cssText='position:fixed;left:-99999px;top:0;border:0;width:360px;height:800px';
    f.src='/dashboard'; document.body.appendChild(f);
    await new Promise(r=>{f.onload=()=>setTimeout(r,450)});
    const d=f.contentDocument;
    const btn=d.querySelector('[data-nav-toggle]');
    const panel=d.querySelector('[data-nav-panel]');
    const before={open:panel.classList.contains('is-open'), display:getComputedStyle(panel).display, aria:btn.getAttribute('aria-expanded')};
    btn.click(); await new Promise(r=>setTimeout(r,120));
    const afterOpen={open:panel.classList.contains('is-open'), display:getComputedStyle(panel).display, aria:btn.getAttribute('aria-expanded')};
    btn.click(); await new Promise(r=>setTimeout(r,120));
    const afterClose={open:panel.classList.contains('is-open'), display:getComputedStyle(panel).display};
    results.navToggle={before,afterOpen,afterClose};
    f.remove();
  }

  // ---- 2. password strength meter + rules + match warning -------------------
  {
    const f=document.createElement('iframe');
    f.style.cssText='position:fixed;left:-99999px;top:0;border:0;width:360px;height:900px';
    f.src='/register'; document.body.appendChild(f);
    await new Promise(r=>{f.onload=()=>setTimeout(r,450)});
    const d=f.contentDocument;
    const pw=d.querySelector('[data-strength-input]');
    const pw2=d.querySelector('#passwordConfirm');
    const meter=d.querySelector('[data-strength-meter]');
    const fill=d.querySelector('[data-strength-fill]');
    const label=d.querySelector('[data-strength-label]');
    const set=v=>{pw.value=v;pw.dispatchEvent(new Event('input',{bubbles:true}))};
    set('');
    const s0={hidden:meter.hidden};
    set('abc');
    const s1={label:label.textContent, width:fill.style.width, metRules:[...d.querySelectorAll('[data-rule].is-met')].map(x=>x.dataset.rule)};
    set('Str0ng@Passw0rd!');
    const s2={label:label.textContent, width:fill.style.width, cls:meter.className};
    // confirm mismatch warning
    pw2.value='different'; pw2.dispatchEvent(new Event('input',{bubbles:true}));
    const mismatchShown=!d.querySelector('[data-match-error]').hidden;
    pw2.value=pw.value; pw2.dispatchEvent(new Event('input',{bubbles:true}));
    const mismatchHidden=d.querySelector('[data-match-error]').hidden;
    // show/hide password
    const tbtn=d.querySelector('[data-password-toggle="password"]');
    const typeBefore=pw.type; tbtn.click(); const typeAfter=pw.type; const btnText=tbtn.textContent;
    results.password={s0,s1,s2,mismatchShown,mismatchHidden,typeBefore,typeAfter,btnText};
    f.remove();
  }

  // ---- 3. character counter on the complaint form ---------------------------
  {
    const f=document.createElement('iframe');
    f.style.cssText='position:fixed;left:-99999px;top:0;border:0;width:360px;height:900px';
    f.src='/complaints/new'; document.body.appendChild(f);
    await new Promise(r=>{f.onload=()=>setTimeout(r,450)});
    const d=f.contentDocument;
    const ta=d.querySelector('[data-char-count]');
    const out=d.querySelector('[data-char-current]');
    const start=out.textContent;
    ta.value='x'.repeat(123); ta.dispatchEvent(new Event('input',{bubbles:true}));
    const after=out.textContent;
    results.charCounter={start,after,ok:start==='0'&&after==='123'};
    f.remove();
  }

  // ---- 4. delete-confirm interception --------------------------------------
  {
    const f=document.createElement('iframe');
    f.style.cssText='position:fixed;left:-99999px;top:0;border:0;width:360px;height:900px';
    f.src='/complaints'; document.body.appendChild(f);
    await new Promise(r=>{f.onload=()=>setTimeout(r,450)});
    const d=f.contentDocument;
    let asked=null;
    const orig=f.contentWindow.confirm;
    f.contentWindow.confirm=function(m){ asked=m; return false; };
    const link=d.querySelector('[data-confirm-link]');
    let prevented=false;
    link.addEventListener('click',e=>{ if(!f.contentWindow.confirm(link.dataset.confirmLink)) prevented=true; }, true);
    link.click();
    results.confirmLink={asked,prevented};
    f.contentWindow.confirm=orig;
    f.remove();
  }

  return JSON.stringify(results,null,1);
})()
` });
return JSON.parse(res.value);

