  const out = {};
  const load = async (path) => {
    const f=document.createElement('iframe');
    f.style.cssText='position:fixed;left:-99999px;top:0;border:0;width:360px;height:900px';
    f.src=path; document.body.appendChild(f);
    await new Promise(r=>{f.onload=()=>setTimeout(r,500)});
    f.contentDocument.querySelectorAll('script[src]').forEach(s=>s.remove());
    const st=f.contentDocument.createElement('script'); st.textContent=js; f.contentDocument.head.appendChild(st);
    await new Promise(r=>setTimeout(r,200));
    return { f, d:f.contentDocument, w:f.contentWindow };
  };

  // --- A. nav toggle, isolated ------------------------------------------------
  {
    const { f, d, w } = await load('/complaints');
    const btn=d.querySelector('[data-nav-toggle]');
    const panel=d.querySelector('[data-nav-panel]');
    out.hasElements = { btn: !!btn, panel: !!panel, panelId: panel && panel.id, ariaControls: btn && btn.getAttribute('aria-controls') };
    const read = () => ({ open:panel.classList.contains('is-open'), display:w.getComputedStyle(panel).display, aria:btn.getAttribute('aria-expanded') });
    const before = read();
    btn.click();
    await new Promise(r=>setTimeout(r,250));
    const afterOpen = read();
    btn.click();
    await new Promise(r=>setTimeout(r,250));
    const afterClose = read();
    out.navToggle = { before, afterOpen, afterClose,
      works: before.display==='none' && afterOpen.open===true && afterOpen.display!=='none' && afterOpen.aria==='true' && afterClose.open===false };
    f.remove();
  }

  // --- B. empty form submit must be blocked (no navigation) ------------------
  {
    const { f, d } = await load('/complaints/new');
    const form=d.querySelector('form.form-stack');
    let navAttempted=false;
    d.defaultView.addEventListener('beforeunload',()=>{navAttempted=true});
    const urlBefore=f.contentWindow.location.href;
    form.querySelector('button[type=submit]').click();
    await new Promise(r=>setTimeout(r,300));
    const invalidCount=d.querySelectorAll('form.form-stack .is-invalid').length;
    out.emptySubmitBlocked={ stillOnSamePage: f.contentWindow.location.href===urlBefore,
      invalidMarked: invalidCount,
      blocked: f.contentWindow.location.href===urlBefore && invalidCount>0 };
    f.remove();
  }

  // --- C. filter select auto-submits (real navigation) -----------------------
  {
    const { f, d } = await load('/complaints');
    const urlBefore=f.contentWindow.location.href;
