input.command:
$root = "C:\Users\USer\OneDrive\Documents\Default Project"
"=== non-ASCII scan on .ps1 ==="
$bad = 0
Get-ChildItem -Path $root -Recurse -Filter *.ps1 | ForEach-Object {
  $n = ([IO.File]::ReadAllBytes($_.FullName) | Where-Object { $_ -gt 127 }).Count
  if ($n -gt 0) { $bad++; "  NON-ASCII: $($_.Name)" }
}
if ($bad -eq 0) { "  clean" }

""
"=== A) second launch while server IS running (should say already running, exit 0) ==="
$out = & powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$root\server.ps1" -NoBrowser 2>&1 | Out-String
$out.Trim()
"exit code: $LASTEXITCODE"

$root = "C:\Users\USer\OneDrive\Documents\Default Project"
# stop the old server by port owner
try { (Get-NetTCPConnection -LocalPort 8080 -State Listen -EA SilentlyContinue).OwningProcess | Sort-Object -Unique | ForEach-Object { Stop-Process -Id $_ -Force -EA SilentlyContinue } } catch {}
Get-Process powershell -EA SilentlyContinue | Where-Object { $_.Id -ne $PID } | ForEach-Object {
  $cl=''; try { $cl=(Get-CimInstance Win32_Process -Filter "ProcessId=$($_.Id)").CommandLine } catch {}
  if ($cl -like '*-File server.ps1*' -or $cl -like '*server.ps1 -NoBrowser*') { Stop-Process -Id $_.Id -Force -EA SilentlyContinue }
}
Start-Sleep -Seconds 3
Remove-Item "$root\data\db.json" -Force -EA SilentlyContinue
Remove-Item "C:\Users\USer\AppData\Local\Temp\opencode\srv.log","C:\Users\USer\AppData\Local\Temp\opencode\srv.err" -EA SilentlyContinue
try { (Get-NetTCPConnection -LocalPort 8080 -State Listen -EA SilentlyContinue) | Out-Null; "8080 STILL BUSY" } catch { "8080 free" }

$p = Start-Process -FilePath "powershell.exe" -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-File','server.ps1','-NoBrowser' -WorkingDirectory $root -RedirectStandardOutput "C:\Users\USer\AppData\Local\Temp\opencode\srv.log" -RedirectStandardError "C:\Users\USer\AppData\Local\Temp\opencode\srv.err" -PassThru
Start-Sleep -Seconds 7
Get-Content "C:\Users\USer\AppData\Local\Temp\opencode\srv.log" | Select-Object -First 3
""
powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$root\test-app.ps1" -Port 8080 2>&1 | Select-String -Pattern 'FAIL|PASSED|ALL TESTS'
powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$root\test-render.ps1" -Port 8080 2>&1 | Select-String -Pattern 'ISSUE|RENDER CHECK|^\s+- '
$s = Get-Content "C:\Users\USer\AppData\Local\Temp\opencode\srv.log" | Select-String -Pattern '! 500'
if ($s) { "500s:"; $s } else { "500s: NONE" }
$e = Get-Content "C:\Users\USer\AppData\Local\Temp\opencode\srv.err" -EA SilentlyContinue
if ($e) { "stderr:"; $e } else { "stderr: (empty)" }
"PID: $($p.Id)"
